  let rgb = select(vec3f(0.0), (warm_rgb * warm_a * (1.0 - grain_a) + grain_rgb * grain_a) / total_a, total_a > 0.001);
  return vec4f(clamp(rgb, vec3f(0.0), vec3f(1.0)), total_a);
